CREATE DATABASE IF NOT EXISTS eventhub_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE eventhub_db;
CREATE TABLE IF NOT EXISTS users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','student','committee') NOT NULL DEFAULT 'student',is_active TINYINT(1) NOT NULL DEFAULT 1,avatar_path VARCHAR(255) NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS student_profiles(user_id BIGINT UNSIGNED PRIMARY KEY,degree VARCHAR(80) DEFAULT 'BCA',year_label VARCHAR(40) DEFAULT '1st Year',university VARCHAR(120) DEFAULT 'Marwadi University',volunteering_hours DECIMAL(7,2) NOT NULL DEFAULT 0,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS event_categories(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(40) NOT NULL UNIQUE,slug VARCHAR(40) NOT NULL UNIQUE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(190) NOT NULL,category VARCHAR(40) NOT NULL,description TEXT,event_date DATE NOT NULL,event_time TIME NOT NULL DEFAULT '09:00:00',end_time TIME NULL,venue VARCHAR(190) NOT NULL,capacity INT UNSIGNED NOT NULL DEFAULT 100,image_path VARCHAR(255) NULL,is_published TINYINT(1) NOT NULL DEFAULT 1,created_by BIGINT UNSIGNED NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,INDEX idx_events_date(event_date),INDEX idx_events_category(category),INDEX idx_events_published(is_published),FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS committee_event_assignments (committee_user_id BIGINT UNSIGNED NOT NULL,event_id BIGINT UNSIGNED NOT NULL,assigned_by BIGINT UNSIGNED NULL,assigned_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(committee_user_id,event_id),INDEX idx_committee_event(event_id),FOREIGN KEY(committee_user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE,FOREIGN KEY(assigned_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS event_applications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,event_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,status ENUM('Pending','Shortlisted','Approved','Rejected','Waitlisted') NOT NULL DEFAULT 'Pending',applied_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_event_applicant(event_id,user_id),INDEX idx_app_user(user_id),FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS event_application_details (application_id BIGINT UNSIGNED NOT NULL PRIMARY KEY,applicant_name VARCHAR(120) NOT NULL,gr_no VARCHAR(40) NOT NULL,mobile_number VARCHAR(20) NOT NULL,department VARCHAR(100) NOT NULL,semester TINYINT UNSIGNED NOT NULL,application_role VARCHAR(80) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(application_id) REFERENCES event_applications(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS event_interests(event_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(event_id,user_id),FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS volunteer_opportunities(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(190) NOT NULL,description TEXT,event_date DATE NOT NULL,venue VARCHAR(190) NOT NULL,created_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS volunteer_applications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,opportunity_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,status ENUM('Pending','Approved','Rejected') DEFAULT 'Pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_volunteer_application(opportunity_id,user_id),FOREIGN KEY(opportunity_id) REFERENCES volunteer_opportunities(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS volunteer_hours(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,opportunity_id BIGINT UNSIGNED NULL,hours DECIMAL(6,2) NOT NULL,notes VARCHAR(255),is_verified TINYINT(1) NOT NULL DEFAULT 0,recorded_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,verified_by BIGINT UNSIGNED NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(opportunity_id) REFERENCES volunteer_opportunities(id) ON DELETE SET NULL,FOREIGN KEY(verified_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS cultural_activities(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,event_id BIGINT UNSIGNED NULL,title VARCHAR(190) NOT NULL,description TEXT,activity_date DATE NOT NULL,venue VARCHAR(190) NOT NULL,FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS activity_registrations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,activity_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_activity_user(activity_id,user_id),FOREIGN KEY(activity_id) REFERENCES cultural_activities(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS announcements(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(190) NOT NULL,body TEXT NOT NULL,created_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS notifications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,title VARCHAR(190) NOT NULL,message TEXT NOT NULL,is_read TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_notifications_user_read(user_id,is_read),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS activity_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,action VARCHAR(100) NOT NULL,details VARCHAR(255),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS user_settings(user_id BIGINT UNSIGNED PRIMARY KEY,email_notifications TINYINT(1) NOT NULL DEFAULT 1,in_app_notifications TINYINT(1) NOT NULL DEFAULT 1,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
INSERT IGNORE INTO event_categories(name,slug) VALUES('Cultural','cultural'),('Technical','technical'),('Sports','sports'),('Volunteer','volunteer');
